    "unknown": [
      {
        "what": "\"사진 없음\" 빗금 영역",
        "where": "5동관 x 2158~2354, y 767~930",
        "note": "안쪽 줄·복도·바깥 줄을 모두 덮고 있어 그 안의 방·복도·계단을 알 수 없다. 5동관 복도 북쪽 구간(y 327~766)과 남쪽 구간(y 931~1435)을 잇지 않았다(두 구간은 5북·5서·5남관 복도를 돌아 이어짐). 1F 계단 5E-ST-Y800(2195,818.5)이 이 영역 안이라 4층 짝을 확인할 수 없다"
      },
      {
        "what": "북동쪽 모서리 계단(5E-ST-Y400) 짝과 관 구분",
        "where": "x 2141~2231, y 371~443",
        "note": "1F의 5E-ST-Y400(x 2159~2231, 중심 2195,407)과 5N-ST-X2100(x 2082~2156, 중심 2119,407) 두 계단 자리에 걸쳐 있다. 중심 차 9px인 5E-ST-Y400로 짝지었고, 1F와 같은 기준(5동관 안쪽 줄 419호 바로 위, 동쪽 변이 5동관 복도에 닿음)으로 5동관 분류. 5동관 복도와 이었다. treadsToNextUp 모름"
      },
      {
        "what": "남동쪽 계단(5E-ST-Y1500) 연결",
        "where": "x 2279~2351, y 1438~1509",
        "note": "1F와 같이 복도와 꼭짓점만 닿고 401A호(5동관)·401호(5남관) 사이에 있다. 노드만 만들고 잇지 않았다. treadsToNextUp 모름"
      },
      {
        "what": "5동관 바깥 줄 흰 빈칸",
        "where": "x 2279~2354, y 486~531 (416·415호 사이) 및 y 931~944",
        "note": "이름 없는 흰 칸. 노드 없음"
      },
      {
        "what": "남동쪽 회색 칸",
        "where": "x 2159~2232, y 1319~1391 (403호 아래, 451호 동쪽)",
        "note": "이름 없는 회색 칸. 통행 여부 불명이라 노드 없음"
      }
    ]
