    "unknown": [
      {
        "what": "북쪽 계단(5E-ST-B1-1)이 1F의 어느 계단과 같은지 확인 필요",
        "where": "가운데 줄 x 1131~1356, y 595~662",
        "note": "1F 북동쪽의 5E-ST-Y400(1F x 2159~2231, y 371~443) 또는 5N-ST-X2100(1F x 2082~2156, y 371~443)과 같은 계단일 수 있으나, B1 도면이 비례가 맞지 않는 안내도이고 서쪽 출구 화살표가 있어 바깥으로만 이어지는 계단일 수도 있다. 1F 계단과 같다고 확인되면 group을 그 이름으로 바꾼다. treadsToNextUp 모름"
      },
      {
        "what": "북쪽 계단 서쪽 출구(초록 화살표)",
        "where": "계단 칸 서쪽 바깥 x 약 1075~1110, y 약 628",
        "note": "'밖으로 나가는 방향' 화살표가 계단 서쪽(중정 쪽)을 가리킨다. 계단을 거쳐 밖으로 나가는 것으로 보고 입구 노드를 계단 노드에만 이었다. 오르는 계단 칸 수는 경로 비용에 들어가지 않는다. 출구 높이(1층 중정 높이인지) 현장 확인 필요"
      },
      {
        "what": "계단·램프(5E-ST-B1-2)가 1F의 어느 계단과 같은지 확인 필요",
        "where": "가운데 줄 x 1131~1356, y 1198~1279",
        "note": "1F 5동관 서쪽 줄 계단 5E-ST-Y800(1F 110호와 107B호 사이)과 같은 자리일 수 있으나 확인할 수 없다. 램프가 있어 계단 없이 다닐 수 있는지도 모른다(지금은 stair로만 둠). treadsToNextUp 모름"
      },
      {
        "what": "계단·램프 서쪽 출구(초록 화살표)",
        "where": "계단·램프 칸 서쪽 바깥 x 약 1075~1110, y 약 1238",
        "note": "북쪽 계단과 같은 방식으로 입구 노드를 만들어 계단 노드에만 이었다. 출구 높이·램프 경사 현장 확인 필요"
      },
      {
        "what": "가운데 줄 맨 위 회색 칸",
        "where": "x 1131~1356, y 467~594 (011호 동쪽, 북쪽 계단 위)",
        "note": "이름 없는 회색 칸. 통행 가능 여부 불명이라 노드를 만들지 않았다"
      },
      {
        "what": "세로 복도 아래쪽 양옆 회색 칸",
        "where": "x 1131~1356, y 1814~1944 및 x 1421~1650, y 1814~1944",
        "note": "이름 없는 회색 칸. 통행 여부 불명. 5동관과 5남관의 경계도 이 부근이라 불분명하다(044호·001호 아래 세로 복도 y 1814~1944 구간은 5동관 마지막 노드와 5남관 갈림길을 잇는 edge로만 표현)"
      },
      {
        "what": "호수만 있는 흰 칸(그 밖의 방)의 관 구분",
        "where": "024·030·042·011·044(기계실)·001(전기실)호",
        "note": "범례상 '그 밖의 방'이라 관 색이 없다. 5동관 두 줄 안에 있고 호수가 5동관 동아리방 번호와 이어져 5E로 분류했다"
      }
    ]
