    "unknown": [
      {
        "what": "북서쪽 모서리 계단(5W-ST-Y300) 연결과 관 구분",
        "where": "x 115~189, y 251~324",
        "note": "5북관 위쪽 줄 서쪽 끝이자 5서관 바깥 줄 위 끝 자리. 1층 규칙(모서리는 세로 줄 관)을 따라 5서관으로 분류. 복도와 꼭짓점만 닿고 사이에 회색 칸(x 191~309 y 251~324, x 115~189 y 327~445)이 있어 들어가는 길을 알 수 없다. 노드만 만들고 잇지 않았다. 1층 같은 자리는 149호라 1층 짝 없음. treadsToNextUp 모름"
      },
      {
        "what": "5서관 안쪽 줄 계단(5W-ST-Y800)의 1층 짝",
        "where": "x 234~309, y 748~821",
        "note": "1F의 5W-ST-Y600과 같은 계단인지 확인 필요. 1층 계단(y 523~640)과 y가 약 200px 어긋나고, 1층에서 바로 옆에 있던 엘리베이터가 2층 이 자리에는 없어 짝이 애매하다. 새 이름을 썼다. treadsToNextUp 모름"
      },
      {
        "what": "5서관 엘리베이터 두 대(5W-EV-Y1200, 5W-EV-Y1300)",
        "where": "바깥 줄 x 115~189 y 1157~1191, 안쪽 줄 x 234~309 y 1261~1323",
        "note": "1층에는 5W-EV-Y600(y 약 617) 한 대뿐이고 2층 두 대와 위치가 550px 이상 달라 짝을 짓지 않았다. 1F의 5W-EV-Y600과 같은 엘리베이터인지, 1층에서 어디에 서는지 확인 필요"
      },
      {
        "what": "남서쪽 계단(5W-ST-Y1400) 관 구분과 칸 수",
        "where": "5남관 안쪽 줄 서쪽 끝 x 234~319, y 1325~1397",
        "note": "1층과 같은 자리라 1층 분류(5서관)와 group 이름을 따랐다. 서쪽·남쪽 변이 복도에 닿아 5서관 복도와 이었다. treadsToNextUp 모름"
      },
      {
        "what": "5서관 바깥 줄 회색 칸",
        "where": "x 115~189, y 327~445 및 y 1324~1399",
        "note": "이름 없는 회색 칸. 통행 가능한 공간인지 알 수 없어 노드를 만들지 않았다"
      },
      {
        "what": "관 경계(모서리 분기점)",
        "where": "복도 모서리 (211.5, 348), (211.5, 1421)",
        "note": "도면에 관 경계선이 없다. 1층처럼 모서리는 세로 줄 관(5서관)에 넣었다. 두 분기점은 5서관 파일에 있다"
      }
    ]
